"""Exact small-system locality hierarchy generated by local Hamiltonian actions."""

from __future__ import annotations

from collections.abc import Callable
from dataclasses import dataclass

import numpy as np


MatrixAction = Callable[[np.ndarray], np.ndarray]


@dataclass(frozen=True)
class LocalBlockKrylovDepth:
    """Ritz and residual diagnostics after one registered Krylov depth."""

    depth: int
    subspace_dimension: int
    hamiltonian_applications: int
    energies: np.ndarray
    residual_norms: np.ndarray
    spectral_intervals: np.ndarray
    seed_subspace_weights: np.ndarray
    orthonormality_error: float
    projected_hamiltonian_antihermitian_error: float
    projected_hamiltonian_relative_antihermitian_error: float


@dataclass(frozen=True)
class LocalBlockKrylovResult:
    """Complete depth trajectory and the final orthonormal Krylov basis."""

    depths: tuple[LocalBlockKrylovDepth, ...]
    basis: np.ndarray
    seed_rank: int
    target_roots: int
    maximum_depth: int
    stopped_after_rank_saturation: bool


def _validated_matrix_action(
    action: MatrixAction, vectors: np.ndarray, dimension: int
) -> np.ndarray:
    result = np.asarray(action(vectors), dtype=np.complex128)
    if result.shape != vectors.shape:
        raise ValueError(
            "Hamiltonian action must preserve the dimension-by-columns shape"
        )
    if result.shape[0] != dimension or np.any(~np.isfinite(result)):
        raise FloatingPointError("Hamiltonian action returned invalid values")
    return result


def _orthogonal_block_increment(
    candidates: np.ndarray,
    basis: np.ndarray,
    relative_rank_tolerance: float,
) -> np.ndarray:
    """Return the numerically new part of a candidate block.

    Rank is measured relative to the *unprojected* candidate block.  Using
    the largest singular value of the residual itself would normalize pure
    roundoff after an invariant-subspace breakdown and manufacture arbitrary
    Krylov directions.
    """

    original = np.asarray(candidates, dtype=np.complex128)
    if original.shape[1] == 0:
        return np.empty((original.shape[0], 0), dtype=np.complex128)
    original_singular = np.linalg.svd(original, compute_uv=False)
    if original_singular.size == 0 or original_singular[0] <= 0.0:
        return np.empty((original.shape[0], 0), dtype=np.complex128)
    values = original.copy()
    for _ in range(2):
        if basis.shape[1]:
            values -= basis @ (basis.conj().T @ values)
    left, singular, _ = np.linalg.svd(values, full_matrices=False)
    retained = singular > relative_rank_tolerance * original_singular[0]
    increment = np.asarray(left[:, retained], dtype=np.complex128)
    if basis.shape[1] and increment.shape[1]:
        for _ in range(2):
            increment -= basis @ (basis.conj().T @ increment)
        left, singular, _ = np.linalg.svd(increment, full_matrices=False)
        if singular.size:
            retained = singular > 64.0 * np.finfo(np.float64).eps * singular[0]
            increment = np.asarray(left[:, retained], dtype=np.complex128)
    return increment


def local_block_krylov_ritz(
    hamiltonian_action: MatrixAction,
    seed_vectors: np.ndarray,
    *,
    maximum_depth: int,
    target_roots: int = 3,
    relative_rank_tolerance: float = 1.0e-11,
    maximum_projected_antihermitian_error: float = 1.0e-10,
) -> LocalBlockKrylovResult:
    """Build a block Krylov space and return every depth's Ritz certificate.

    ``seed_vectors`` has shape ``(Hilbert dimension, number of seeds)``.  The
    reported depth zero is the orthonormalized seed span.  One batched call to
    ``hamiltonian_action`` is made per newly accepted frontier.  Its cached
    image supplies both the projected matrix and direct Ritz residuals, so no
    second action is hidden in the work ledger.

    The caller must supply a deterministic linear Hermitian action.  The
    routine fails closed if its projection on the explored space violates
    Hermiticity, but a callable alone cannot certify Hermiticity outside that
    space.
    """

    seeds = np.asarray(seed_vectors, dtype=np.complex128)
    if seeds.ndim != 2 or seeds.shape[0] < 1 or seeds.shape[1] < 1:
        raise ValueError("seed_vectors must be a nonempty dimension-by-seed matrix")
    if np.any(~np.isfinite(seeds)):
        raise FloatingPointError("seed vectors must be finite")
    if (
        isinstance(maximum_depth, bool)
        or not isinstance(maximum_depth, int)
        or maximum_depth < 0
    ):
        raise ValueError("maximum_depth must be a nonnegative integer")
    if (
        isinstance(target_roots, bool)
        or not isinstance(target_roots, int)
        or target_roots < 1
    ):
        raise ValueError("target_roots must be a positive integer")
    if (
        not np.isfinite(relative_rank_tolerance)
        or not 0.0 < relative_rank_tolerance < 1.0
    ):
        raise ValueError("relative_rank_tolerance must lie between zero and one")
    if (
        not np.isfinite(maximum_projected_antihermitian_error)
        or maximum_projected_antihermitian_error <= 0.0
    ):
        raise ValueError(
            "maximum_projected_antihermitian_error must be finite and positive"
        )

    dimension = seeds.shape[0]
    empty = np.empty((dimension, 0), dtype=np.complex128)
    seed_basis = _orthogonal_block_increment(
        seeds, empty, relative_rank_tolerance
    )
    seed_rank = int(seed_basis.shape[1])
    if seed_rank < target_roots:
        raise ValueError(
            f"seed span rank {seed_rank} is smaller than target_roots={target_roots}"
        )

    basis = seed_basis
    frontier = seed_basis
    h_basis = np.empty((dimension, 0), dtype=np.complex128)
    applications = 0
    rows: list[LocalBlockKrylovDepth] = []
    saturated = False
    for depth in range(maximum_depth + 1):
        h_frontier = _validated_matrix_action(
            hamiltonian_action, frontier, dimension
        )
        applications += 1
        h_basis = np.column_stack((h_basis, h_frontier))
        projected_raw = basis.conj().T @ h_basis
        antihermitian = float(
            np.max(np.abs(projected_raw - projected_raw.conj().T), initial=0.0)
        )
        matrix_scale = max(
            float(np.max(np.abs(projected_raw), initial=0.0)),
            np.finfo(np.float64).tiny,
        )
        relative_antihermitian = antihermitian / matrix_scale
        if (
            not np.isfinite(relative_antihermitian)
            or relative_antihermitian > maximum_projected_antihermitian_error
        ):
            raise FloatingPointError(
                "projected Hamiltonian is not Hermitian: "
                f"relative_error={relative_antihermitian:.6e}"
            )
        projected = 0.5 * (projected_raw + projected_raw.conj().T)
        values, vectors = np.linalg.eigh(projected)
        coefficients = vectors[:, :target_roots]
        roots = basis @ coefficients
        h_roots = h_basis @ coefficients
        energies = np.asarray(values[:target_roots], dtype=np.float64)
        residuals = h_roots - roots * energies[None, :]
        residual_norms = np.linalg.norm(residuals, axis=0)
        seed_weights = np.sum(
            np.abs(seed_basis.conj().T @ roots) ** 2, axis=0
        )
        orthonormality = float(
            np.max(
                np.abs(basis.conj().T @ basis - np.eye(basis.shape[1])),
                initial=0.0,
            )
        )
        rows.append(
            LocalBlockKrylovDepth(
                depth=depth,
                subspace_dimension=int(basis.shape[1]),
                hamiltonian_applications=applications,
                energies=energies,
                residual_norms=np.asarray(residual_norms, dtype=np.float64),
                spectral_intervals=np.stack(
                    (energies - residual_norms, energies + residual_norms), axis=1
                ),
                seed_subspace_weights=np.asarray(seed_weights, dtype=np.float64),
                orthonormality_error=orthonormality,
                projected_hamiltonian_antihermitian_error=antihermitian,
                projected_hamiltonian_relative_antihermitian_error=(
                    relative_antihermitian
                ),
            )
        )
        if basis.shape[1] == dimension:
            saturated = True
            break
        if depth == maximum_depth:
            break
        increment = _orthogonal_block_increment(
            h_frontier, basis, relative_rank_tolerance
        )
        if increment.shape[1] == 0:
            saturated = True
            break
        basis = np.column_stack((basis, increment))
        frontier = increment

    return LocalBlockKrylovResult(
        depths=tuple(rows),
        basis=basis,
        seed_rank=seed_rank,
        target_roots=target_roots,
        maximum_depth=maximum_depth,
        stopped_after_rank_saturation=saturated,
    )


def optimal_polynomial_filter(
    hamiltonian,
    initial: np.ndarray,
    *,
    depth: int,
) -> tuple[np.ndarray, np.ndarray]:
    """Return the lowest-energy normalized state and monomial coefficients.

    The coefficients obey ``filtered = sum_k c[k] H**k initial``.  This raw
    monomial form is intended for low-depth connectivity/importance-sampling
    diagnostics; the orthonormal basis remains preferable numerically.
    """

    if depth < 0:
        raise ValueError("depth must be nonnegative")
    source = np.asarray(initial, dtype=np.complex128)
    columns = [source]
    for _ in range(depth):
        columns.append(np.asarray(hamiltonian @ columns[-1]))
    raw = np.column_stack(columns)
    basis, upper = np.linalg.qr(raw, mode="reduced")
    projected = basis.conj().T @ (hamiltonian @ basis)
    projected = 0.5 * (projected + projected.conj().T)
    _, eigenvectors = np.linalg.eigh(projected)
    ritz_coordinates = eigenvectors[:, 0]
    coefficients = np.linalg.solve(upper, ritz_coordinates)
    filtered = raw @ coefficients
    filtered /= np.linalg.norm(filtered)
    coefficients /= np.linalg.norm(raw @ coefficients)
    return filtered, coefficients


def importance_sampling_diagnostics(
    initial: np.ndarray,
    filtered: np.ndarray,
    *,
    zero_tolerance: float = 0.0,
) -> dict[str, float]:
    """Exact reweighting diagnostics when sampling ``|initial|**2``.

    The effective-sample-size fraction is one for constant weights and tends
    to zero when a few base samples dominate the filtered expectation.
    """

    source = np.asarray(initial, dtype=np.complex128)
    target = np.asarray(filtered, dtype=np.complex128)
    source = source / np.linalg.norm(source)
    target = target / np.linalg.norm(target)
    probabilities = np.abs(source) ** 2
    target_probabilities = np.abs(target) ** 2
    support = probabilities > zero_tolerance
    leaked = float(np.sum(target_probabilities[~support]))
    supported_target = target_probabilities[support]
    supported_base = probabilities[support]
    mean_weight = float(np.sum(supported_target))
    positive_target = supported_target > 0.0
    if np.any(positive_target):
        log_second_terms = (
            2.0 * np.log(supported_target[positive_target])
            - np.log(supported_base[positive_target])
        )
        maximum_log = float(np.max(log_second_terms))
        log_second_moment = maximum_log + float(
            np.log(np.sum(np.exp(log_second_terms - maximum_log)))
        )
        log_ess = 2.0 * np.log(mean_weight) - log_second_moment
        ess_fraction = float(np.exp(log_ess))
        log_weights = (
            np.log(supported_target[positive_target])
            - np.log(supported_base[positive_target])
            - np.log(mean_weight)
        )
        maximum_normalized_weight = float(np.exp(np.max(log_weights)))
        second_moment = float(np.exp(log_second_moment))
    else:
        ess_fraction = 0.0
        maximum_normalized_weight = 0.0
        second_moment = 0.0
    return {
        "effective_sample_size_fraction": ess_fraction,
        "target_weight_outside_base_support": leaked,
        "maximum_normalized_weight": maximum_normalized_weight,
        "weight_second_moment": second_moment,
    }


def adaptive_local_imaginary_time_step(
    hamiltonian,
    state: np.ndarray,
    *,
    minimum_ess_fraction: float = 0.5,
    maximum_tau: float = 0.25,
    grid_size: int = 257,
    minimum_tau_ratio: float = 1e-12,
) -> tuple[np.ndarray, dict[str, float]]:
    """Choose an ESS-controlled local imaginary-time Euler step.

    The target is ``(I - tau * (H-E)) state``.  In production it must be
    distilled back into a normalized autoregressive model after every step;
    here the exact target quantifies the best-case layer behavior.
    """

    if not 0.0 < minimum_ess_fraction <= 1.0:
        raise ValueError("minimum_ess_fraction must lie in (0, 1]")
    if maximum_tau <= 0.0 or grid_size < 4:
        raise ValueError("maximum_tau must be positive and grid_size at least two")
    if not 0.0 < minimum_tau_ratio < 1.0:
        raise ValueError("minimum_tau_ratio must lie in (0, 1)")
    source = np.asarray(state, dtype=np.complex128)
    source /= np.linalg.norm(source)
    h_source = np.asarray(hamiltonian @ source)
    energy_before = float(np.real(np.vdot(source, h_source)))
    direction = h_source - energy_before * source
    best_state = source
    best = {
        "tau": 0.0,
        "energy_before": energy_before,
        "energy_after": energy_before,
        "variance_after": float(np.real(np.vdot(direction, direction))),
        "effective_sample_size_fraction": 1.0,
        "maximum_normalized_weight": 1.0,
    }
    # A purely linear grid silently returns tau=0 for quasi-nodal states whose
    # ESS-safe scale can be orders of magnitude below maximum_tau.  Resolve
    # both that boundary layer and the ordinary finite-tau optimum.
    logarithmic_size = grid_size // 2
    linear_size = grid_size - logarithmic_size
    tau_grid = np.unique(
        np.concatenate(
            (
                np.geomspace(
                    maximum_tau * minimum_tau_ratio,
                    maximum_tau,
                    logarithmic_size,
                ),
                np.linspace(maximum_tau / linear_size, maximum_tau, linear_size),
            )
        )
    )
    h_direction = np.asarray(hamiltonian @ direction)
    for tau in tau_grid:
        candidate = source - tau * direction
        normalization = float(np.linalg.norm(candidate))
        candidate /= normalization
        diagnostics = importance_sampling_diagnostics(source, candidate)
        if diagnostics["effective_sample_size_fraction"] < minimum_ess_fraction:
            continue
        h_candidate = (h_source - tau * h_direction) / normalization
        energy = float(np.real(np.vdot(candidate, h_candidate)))
        if energy < best["energy_after"]:
            variance = float(
                max(np.real(np.vdot(h_candidate, h_candidate)) - energy**2, 0.0)
            )
            best_state = candidate
            best = {
                "tau": float(tau),
                "energy_before": energy_before,
                "energy_after": energy,
                "variance_after": variance,
                "effective_sample_size_fraction": diagnostics[
                    "effective_sample_size_fraction"
                ],
                "maximum_normalized_weight": diagnostics[
                    "maximum_normalized_weight"
                ],
            }
    return best_state, best


def local_krylov_hierarchy(
    hamiltonian,
    initial: np.ndarray,
    *,
    maximum_depth: int,
    reference: np.ndarray | None = None,
    breakdown_tolerance: float = 1e-12,
) -> list[dict[str, float]]:
    """Return optimal Ritz states in ``span{psi, H psi, ..., H**K psi}``.

    For a sum of local bond terms, depth ``K`` is a sum over paths of at most
    ``K`` successive local actions.  The calculation is an exact diagnostic,
    not an efficient sampler or a claim that the filtered state remains
    autoregressive.
    """

    if maximum_depth < 0:
        raise ValueError("maximum_depth must be nonnegative")
    vector = np.asarray(initial, dtype=np.complex128)
    if vector.ndim != 1 or hamiltonian.shape != (len(vector), len(vector)):
        raise ValueError("initial vector and Hamiltonian dimensions do not match")
    norm = float(np.linalg.norm(vector))
    if not np.isfinite(norm) or norm <= 0.0:
        raise ValueError("initial vector must have positive finite norm")
    q_vectors: list[np.ndarray] = [vector / norm]
    ref = None
    if reference is not None:
        ref = np.asarray(reference, dtype=np.complex128)
        ref = ref / np.linalg.norm(ref)
    rows: list[dict[str, float]] = []
    for depth in range(maximum_depth + 1):
        basis = np.column_stack(q_vectors)
        projected = basis.conj().T @ (hamiltonian @ basis)
        projected = 0.5 * (projected + projected.conj().T)
        eigenvalues, eigenvectors = np.linalg.eigh(projected)
        state = basis @ eigenvectors[:, 0]
        state /= np.linalg.norm(state)
        h_state = hamiltonian @ state
        energy = float(np.real(np.vdot(state, h_state)))
        variance = float(max(np.real(np.vdot(h_state, h_state)) - energy**2, 0.0))
        row = {
            "depth": float(depth),
            "subspace_dimension": float(len(q_vectors)),
            "energy": energy,
            "variance": variance,
        }
        if ref is not None:
            row["overlap_squared"] = float(abs(np.vdot(ref, state)) ** 2)
        rows.append(row)
        if depth == maximum_depth:
            break
        candidate = hamiltonian @ q_vectors[-1]
        # Two passes make the exact diagnostic stable even near convergence.
        for _ in range(2):
            for q_vector in q_vectors:
                candidate -= q_vector * np.vdot(q_vector, candidate)
        candidate_norm = float(np.linalg.norm(candidate))
        if candidate_norm <= breakdown_tolerance:
            break
        q_vectors.append(candidate / candidate_norm)
    return rows
